# State Files, Providers & Resources

## Terraform State

Terraform keeps a **state file** (`terraform.tfstate`) that maps your config to real cloud resources. It's the source of truth.

```json
{
  "resources": [{
    "type": "aws_instance",
    "name": "web",
    "instances": [{
      "attributes": {
        "id": "i-abc123",
        "ami": "ami-0c55b159cbfafe1f0",
        "public_ip": "54.123.45.67"
      }
    }]
  }]
}
```

### Remote State (Production)

Never store state locally in production. Use a remote backend:

```hcl
terraform {
  backend "s3" {
    bucket         = "flybeta-terraform-state"
    key            = "prod/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"  # state locking
    encrypt        = true
  }
}
```

## Providers

Providers are plugins that interface with cloud APIs:

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    google = {
      source  = "hashicorp/google"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "google" {
  project = "flybeta-prod"
  region  = "us-central1"
}
```

## Resource Types

### Compute
```hcl
resource "aws_instance" "app" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.medium"
  key_name      = "my-key"
  subnet_id     = aws_subnet.public.id

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
  }
}
```

### Networking
```hcl
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags       = { Name = "flybeta-vpc" }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "web" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

### Database
```hcl
resource "aws_db_instance" "postgres" {
  engine               = "postgres"
  engine_version       = "16.1"
  instance_class       = "db.t3.micro"
  allocated_storage    = 20
  db_name              = "flybeta"
  username             = var.db_username
  password             = var.db_password
  skip_final_snapshot  = true
}
```

## Resource Dependencies

Terraform builds a **dependency graph** automatically:

```hcl
# Terraform knows: VPC → Subnet → Instance
resource "aws_instance" "app" {
  subnet_id = aws_subnet.public.id  # implicit dependency
}
```

# Hands-On: Provision a Full Stack with Terraform

Build a complete web application infrastructure — VPC, subnets, security groups, EC2 instance, and RDS database — all defined in code.

## Project Structure

```
flybeta-infra/
├── main.tf
├── variables.tf
├── outputs.tf
├── terraform.tfvars
└── modules/
    └── (optional)
```

## main.tf

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  tags = { Name = "${var.project}-vpc" }
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "${var.region}a"
  map_public_ip_on_launch = true
  tags = { Name = "${var.project}-public" }
}

# Private Subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.10.0/24"
  availability_zone = "${var.region}a"
  tags = { Name = "${var.project}-private" }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Security Groups
resource "aws_security_group" "web" {
  name   = "${var.project}-web-sg"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.my_ip]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# EC2 Instance
resource "aws_instance" "web" {
  ami                    = var.ami_id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.web.id]
  key_name               = var.key_name

  user_data = <<-EOF
    #!/bin/bash
    apt-get update
    apt-get install -y nginx
    systemctl start nginx
  EOF

  tags = {
    Name        = "${var.project}-web"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}
```

## variables.tf

```hcl
variable "project"       { default = "flybeta" }
variable "region"        { default = "us-east-1" }
variable "environment"   { default = "dev" }
variable "instance_type" { default = "t3.micro" }
variable "ami_id"        { default = "ami-0c55b159cbfafe1f0" }
variable "key_name"      { type = string }
variable "my_ip"         { type = string }
```

## outputs.tf

```hcl
output "web_url"    { value = "http://${aws_instance.web.public_ip}" }
output "ssh_command" { value = "ssh -i ~/.ssh/${var.key_name}.pem ubuntu@${aws_instance.web.public_ip}" }
```

## Deploy

```bash
terraform init
terraform plan -var-file=dev.tfvars
terraform apply -var-file=dev.tfvars

# Visit the output URL!
curl $(terraform output -raw web_url)
```

## Challenge

Add an RDS PostgreSQL instance in the private subnet and output the connection string. Make sure the web server's security group can reach the database on port 5432.
